module debounce(
    input clk,
    input rst_n,
    input button_in,
    output reg button_out
);

reg [4:0] counter;
reg prev_button_in;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 0;
        button_out <= 0;
        prev_button_in <= button_in;
    end else begin
        if (button_in == prev_button_in) begin
            if (counter < 20) begin
                counter <= counter + 1;
            end else begin
                button_out <= button_in;
            end
        end else begin
            counter <= 0;
        end
        prev_button_in <= button_in;
    end
end

endmodule

