module top_module(
                sCLK,
                sRST,
                dCLK,
                sEN,
                sD_IN,
                dD_OUT
                );parameter init = 1'b0;       // initial value for all registers

   // Signals on source clock (sCLK)
   input     sCLK;
   input     sRST;
   input     sEN;
   input     sD_IN;

   // Signals on destination clock (dCLK)
   input     dCLK;
   output    dD_OUT;

   reg       sSyncReg;
   reg       dSyncReg1, dSyncReg2;

   assign    dD_OUT = dSyncReg2 ;

   always @(posedge sCLK or posedge sRST)
      begin
         if (sRST)
            begin
               sSyncReg <= init ;
            end // if (sRST)
         else
            begin
               if ( sEN )
                 begin
                    sSyncReg <= #(dCLK/2) (sD_IN == 1'b1) ? 1'b1 : 1'b0  ;
                 end // if ( sEN )
            end // else: !if(sRST)
      end // always @ (posedge sCLK or posedge sRST)

   always @(posedge dCLK or posedge sRST)
      begin
         if (sRST)
            begin
               dSyncReg1 <= init ;
               dSyncReg2 <= init ;
            end // if (sRST)
         else
            begin
               dSyncReg1 <= #(sCLK/2) sSyncReg ; // clock domain crossing
               dSyncReg2 <= #(sCLK/2) dSyncReg1 ;
            end // else: !if(sRST)
      end // always @ (posedge dCLK or posedge sRST)

endmodule

