module debounce(
    input        clk,
    input        rst_n,
    input        button,
    output reg   debounced_out
);
reg [19:0] counter;  // 20-bit counter to count 1,000,000 clock cycles
reg button_sync;     // Synchronized button input

// Synchronize button input to clock
always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        button_sync <= 0;
    else
        button_sync <= button;
end

// Debounce counter and output
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 20'd0;
        debounced_out <= 0;
    end else begin
        if (button_sync == debounced_out) begin
            counter <= 20'd0;
        end else begin
            counter <= counter + 1;
            if (counter == 20'd999_999) begin
                debounced_out <= button_sync;
                counter <= 20'd0;
            end
        end
    end
end

endmodule

