description:
Design a clocked circuit that generates a square wave output with a 50% duty cycle based on a divided clock signal. The module takes a system clock and an asynchronous active-high reset as inputs. It first divides the input clock frequency by toggling a clock signal on each rising edge. Then, it implements a 4-bit binary counter that increments on the divided clock and resets when it reaches a count of 15 (i.e., binary 1111). The output signal changes state to generate a square wave: it remains low for the first half of the counter's range (counts 0 to 7) and high for the second half (counts 8 to 15), allowing for a clear square wave output with a frequency that is half of the divided clock.
module top_module(
    input clk,        // System clock
    input reset,      // Asynchronous active-high reset
    output reg out    // Output of the functional module
);

code:
module top_module(
    input clk,        // System clock
    input reset,      // Asynchronous active-high reset
    output reg out    // Output of the functional module
);reg clk_divided;
reg [3:0] count;

// Edge detection module
always @(posedge clk) begin
    clk_divided <= ~clk_divided;
end

// 4-bit binary counter module
always @(posedge clk_divided or posedge reset) begin
    if (reset) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
        if (count == 4'b1111) begin
            count <= 4'b0000;
        end
    end
end

// Functional module to generate square wave with 50% duty cycle
always @(posedge clk_divided or posedge reset) begin
    if (reset) begin
        out <= 1'b0;
    end else begin
        if (count < 4'b1000) begin
            out <= 1'b0;
        end else begin
            out <= 1'b1;
        end
    end
end

endmodule

