  wire [31:0]
    w1,
    w32,
    w31,
    w4,
    w27,
    w13824,
    w13855,
    w27710;

  assign w1 = i_data0;
  assign w32 = w1 << 5;
  assign w31 = w32 - w1;
  assign w4 = w1 << 2;
  assign w27 = w31 - w4;
  assign w13824 = w27 << 9;
  assign w13855 = w31 + w13824;
  assign w27710 = w13855 << 1;

  assign o_data0 = w27710;

