module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter S=2'b00, T=2'b01, U=2'b10, V=2'b11;

    always_comb begin
		case (state)
			S: next_state = in1 ? U : T;
			T: next_state = in2 ? V : U;
			U: next_state = in1 ? S : V;
			V: next_state = in2 ? T : S;
		endcase
    end

    always_comb begin
		case (state)
			S: out = 0;
			T: out = 1;
			U: out = 0;
			V: out = 1;
		endcase
    end

endmodule

