module moore_machine (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter T=0, U=1, V=2, W=3;

    always_comb begin
        case (state)
            T: next_state = (in1 && !in2) ? V : (in2 && !in1) ? U : T;
            U: next_state = (in1 && in2) ? V : (!in1 && !in2) ? T : U;
            V: next_state = (in1 && !in2) ? U : (in2 && !in1) ? W : V;
            W: next_state = (in1 && in2) ? T : (!in1 && !in2) ? V : W;
        endcase
    end

    assign out = (state == U) || (state == W);

endmodule

