module top_module(
  input clk,
  input reset,
  output reg green,
  output reg yellow,
  output reg red
);parameter Green = 2'b00;
  parameter Yellow = 2'b01;
  parameter Red = 2'b10;

  reg [1:0] state;
  reg [3:0] count;

  always @(posedge clk) begin
    if (reset) begin
      state <= Green;
      count <= 4'b0;
    end else begin
      case (state)
        Green: begin
          green <= 1'b1;
          yellow <= 1'b0;
          red <= 1'b0;
          if (count == 4'd9) begin
            state <= Yellow;
            count <= 4'b0;
          end else begin
            count <= count + 1;
          end
        end
        Yellow: begin
          green <= 1'b0;
          yellow <= 1'b1;
          red <= 1'b0;
          if (count == 4'd4) begin
            state <= Red;
            count <= 4'b0;
          end else begin
            count <= count + 1;
          end
        end
        Red: begin
          green <= 1'b0;
          yellow <= 1'b0;
          red <= 1'b1;
          if (count == 4'd14) begin
            state <= Green;
            count <= 4'b0;
          end else begin
            count <= count + 1;
          end
        end
      endcase
    end
  end
endmodule

