module top_module(
	output reg forward_a, forward_b,
	input reg_write_mem,
	input [4:0] reg_w_addr_mem, rs_id, rt_id
    );always @ (*)
	begin
		if (reg_write_mem && reg_w_addr_mem && reg_w_addr_mem == rs_id)
			forward_a = 1'b1;
		else
			forward_a = 1'b0;

		if (reg_write_mem && reg_w_addr_mem && reg_w_addr_mem == rt_id)
			forward_b = 1'b1;
