module top_module(
    input clk,
    input [7:0] in,
    output reg [7:0] out
);reg [7:0] any_edge_out;
reg [2:0] shift_reg [0:7];
reg [7:0] shift_and_out;

always @(posedge clk) begin
    any_edge_out <= in ^ any_edge_out;
    shift_reg[0] <= any_edge_out[0];
    shift_reg[1] <= shift_reg[0];
    shift_reg[2] <= shift_reg[1];
    shift_reg[3] <= shift_reg[2];
    shift_reg[4] <= shift_reg[3];
    shift_reg[5] <= shift_reg[4];
    shift_reg[6] <= shift_reg[5];
    shift_reg[7] <= shift_reg[6];
    shift_and_out <= shift_reg[0] & shift_reg[1] & shift_reg[2];
    out <= shift_and_out & any_edge_out;
end

