  input clk,
  input load,
  input [3:0] p,
  output reg [3:0] q,
  output reg [3:0] q_bar
);always @(posedge clk) begin
    if (load) begin
      q <= p;
      q_bar <= ~p;
    end else begin
      q <= {q[2:0], 1'b0};
      q_bar <= ~{q[2:0], 1'b0};
    end
  end

endmodule

module top_module(
  input [7:0] A,
  input [7:0] B,
  input operation,
  input reset,
  output reg [7:0] C
);integer result;

  always @(*) begin
    if (reset) begin
      C <= 8'b0;
    end else if (operation) begin
      result = A - B;
      C <= result;
    end else begin
      result = A + B;
      C <= result;
    end
  end

endmodule

