            count <= 4'b0;
            max_min <= 1'b0;
        end
        else if (enable) begin
            if (control) begin
                if (count == 4'b1111) begin
                    count <= 4'b0;
                    max_min <= 1'b1;
                end
                else begin
                    count <= count + 1;
                    max_min <= 1'b0;
                end
            end
            else begin
