module top_module(
	input clk,
	input enable, 
	input load, 
	input up, 
	input clr, 
	input [3:0] d, 
	output [3:0] q, 
	output co
);reg[3:0] counter;
	reg carry;

	always @(posedge clk) begin
		if(clr == 1'b0) begin
			counter = 4'hx;
			carry = 1'b0;
		end else if(enable == 1'b1) begin
			if(load == 1'b1) begin
				counter = d;
				carry = 1'b0;
			end else if(up == 1'b1) begin
				if(q == 4'b1001) begin
					counter = 4'b0000;
					carry = 1'b1;
				end else begin
					counter = q + 1;
				end 
			end else begin 
				if(q == 4'b0000) begin
					counter = 4'b0000;
					carry = 1'b1;
				end else begin
					counter = q - 1;
				end 
			end
		end else begin
			counter <= q;
			carry <= co;
		end
	end

	assign q = counter;
	assign co = carry;

endmodule

module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter U=0, V=1, W=2, X=3;

    always_comb begin
		case (state)
			U: next_state = in1 ? W : V;
			V: next_state = in1 ? X : W;
			W: next_state = in1 ? U : X;
			X: next_state = in1 ? V : U;
		endcase
    end

    always_comb begin
		case (state)
			U: out = (in1 || in2) ? 1 : 0;
			V: out = (in1 && ~in2) ? 0 : 1;
			W: out = (~in1 && in2) ? 1 : 0;
			X: out = (in1 && in2) ? 0 : 1;
		endcase
    end

endmodule

module top_module(
	input [31:0] dividend,
