assign sub_add = r_sign?({reg_r,q[31]}+{1'b0,reg_b}):({reg_r,q[31]}-{1'b0,reg_b});
assign r = r_sign?reg_r+reg_b:reg_r;
assign q = reg_q ;
always @(negedge clock or posedge reset) begin
	if (reset) begin      

		count<=5'b0;
		busy<=0;

	end
	else begin

		if(start)begin    
			reg_r<=31'b0;
			r_sign<=0;
			reg_q<=dividend;
			reg_b<=divisor;
