	input read_en;
	output reg [7:0] data_out; // Change to reg to allow assignment in always block
	output empty;
	output full;
	output [3:0] count;

	reg [7:0] fifo_mem [0:15];
	reg [3:0] head;
	reg [3:0] tail;
	reg [3:0] count_reg;
	assign full = (count_reg == 16); // Change to assign statement
	assign empty = (count_reg == 0);  // Change to assign statement
	assign count = count_reg;          // Change to assign statement

	always @(posedge clock or posedge reset) begin
		if (reset) begin
			head <= 0;
			tail <= 0;
			count_reg <= 0;
		end else begin
			if (write_en && !full) begin
				fifo_mem[head] <= data_in;
				head <= (head == 15) ? 0 : head + 1;
				count_reg <= count_reg + 1;
			end
			if (read_en && !empty) begin
				data_out <= fifo_mem[tail]; // data_out is now a reg, so this assignment is valid
				tail <= (tail == 15) ? 0 : tail + 1;
				count_reg <= count_reg - 1;
			end
		end
	end

endmodule

