description:
Design a clock generation module that derives multiple lower-frequency clock signals from a 50 MHz input clock. The module generates a 25 MHz clock and uses an internal counter to create additional clocks at 12.5 MHz, 6 MHz, and 3 MHz frequencies based on the 50 MHz signal. The output clock, clk_o, is set to the 12.5 MHz clock signal, providing a stable clock source suitable for various applications requiring lower frequency timing.
module top_module(
    input wire clk_50m_i,
    input wire clk_11m_i,
    output reg clk_o
);

code:
module top_module(
    input wire clk_50m_i,
    input wire clk_11m_i,
    output reg clk_o
);reg clk_25m;
    reg clk_12_5m;
    reg clk_6m;
    reg clk_3m;

    reg[2:0] inner_clk_counter;

    always @ ( posedge clk_50m_i ) begin
        clk_25m <= ~clk_25m;
        inner_clk_counter <= inner_clk_counter + 1;
        if (inner_clk_counter[0] == 0) clk_12_5m <= ~clk_12_5m;
        if (inner_clk_counter[1:0] == 0) clk_6m <= ~clk_6m;
        if (inner_clk_counter[2:0] == 0) clk_3m <= ~clk_3m;
    end

    always @ ( * ) begin
        clk_o = clk_12_5m;
    end


endmodule

