module top_module(
    input clock, reset, start,
    input [7:0] multiplicand, multiplier,
    output [15:0] PR,
    output Ready
);reg [7:0] mult_reg; // register to hold the current digit of the multiplier being processed
reg [15:0] PR_reg; // register to hold the current partial product
reg [3:0] counter; // counter to keep track of the current digit of the multiplier being processed
reg [1:0] state; // state machine state

assign PR = PR_reg;
assign Ready = (state == 2);

always @(posedge clock) begin
    if (reset) begin
        mult_reg <= 0;
        PR_reg <= 0;
        counter <= 0;
        state <= 0;
    end else begin
        case (state)
            0: begin // idle state, waiting for start signal
                if (start) begin
                    mult_reg <= multiplier;
                    counter <= 0;
                    PR_reg <= 0;
                    state <= 1;
                end
            end
            1: begin // multiplication state, processing each digit of the multiplier
                if (counter == 8) begin
                    state <= 2;
                end else begin
                    PR_reg <= PR_reg + (multiplicand << (counter * 8)) * mult_reg[0];
                    mult_reg <= {mult_reg[6:0], mult_reg[7]};
                    counter <= counter + 1;
                end
            end
            2: begin // multiplication complete, waiting for start signal to begin new operation
                if (!start) begin
                    state <= 0;
                end
            end
        endcase
    end
end

