module top_module(
    input CLK,
    input RESET,
    input EN_IN,
    input NEW_FRAME,
    input [15:0] FRAME_WAIT,
    output EN_OUT
    );reg en_out;
    reg [15:0] frames;   

    always @ (posedge CLK) begin
        if (!EN_IN || !RESET) begin
            en_out <= 1'b0;
            frames <= 0;
        end
        else if (EN_IN && NEW_FRAME) begin
            if (frames == FRAME_WAIT) begin
                frames <= 0;
                en_out <= 1'b1;
            end
            else begin
                frames <= frames + 1;
                en_out <= 1'b0;
            end
        end
    end

    assign EN_OUT = en_out;endmodule

module top_module(q,d,rst_n,clk,ini_state);output reg q;
input clk,rst_n,d,ini_state;
always @(posedge clk or negedge rst_n)  
 if (~rst_n)  
 q <= ini_state;       
 else  
 q <= d;endmodule

